let operationMetadata={};
function operationsCard(){return `<details class="card"><summary>Добавить расчётную операцию</summary><div class="cardhead"><h2>Расчёт технологических операций</h2><button onclick="ratesDialog()">Внутренние ставки</button></div><p class="small">Добавьте обработку на одно изделие и подготовку на всю партию. Материал учитывается отдельно. Накладные, наценка и НДС начисляются в общем расчёте.</p><div class="mini-actions">${Object.entries(OperationsCore.TYPES).map(([k,v])=>`<button onclick="operationDialog(null,'${k}')">＋ ${esc(v.name)}</button>`).join('')}</div></details>`}
function operationDialog(id,type){
 OperationEditorStore.setScope(state.draftId||state.libraryId||state.name+'|'+state.code);
 const saved=OperationEditorStore.load(id,type||state.lines.find(x=>x.id===id)?.operation?.type),l=saved?{...state.lines.find(x=>x.id===id),...saved}:state.lines.find(x=>x.id===id),o=l?.operation||{type,mode:'tariff',setup:null,minimum:0,manual:null,measure:null,rate:null,pierces:0,pierceRate:0,minutes:null,hourRate:null,consumables:0},t=OperationsCore.TYPES[o.type];if(!t)return;operationMetadata=Object.fromEntries(['materialCode','thickness','equipment','quality','unit'].map(k=>[k,o[k]??(k==='thickness'?null:'')]));
 const input=(k,label)=>`<div class="field"><label for="op-${k}">${label}</label><input id="op-${k}" type="number" min="0" step="any" value="${esc(o[k]??'')}" oninput="operationPreview()"></div>`;
 modal(t.name,`<form oninput="rememberOperationDraft()" onchange="rememberOperationDraft()" onsubmit="saveOperation(event)">${typeof ratePickerHTML==='function'?ratePickerHTML(o):''}<input id="op-id" type="hidden" value="${esc(id||'')}"><input id="op-type" type="hidden" value="${esc(o.type)}"><div class="field"><label for="op-name">Название операции</label><input id="op-name" value="${esc(l?.name||t.name)}" required></div><div class="grid2"><div class="field"><label for="op-material">Материал и толщина / заготовка</label><input id="op-material" value="${esc(o.material||'')}"></div><div class="field"><label for="op-group">Группа деталей</label><input id="op-group" list="operation-groups" value="${esc(l?.group||'Общее изделие')}"></div></div><datalist id="operation-groups">${[...new Set(state.lines.map(x=>x.group).filter(Boolean))].map(g=>`<option value="${esc(g)}"></option>`).join('')}</datalist><div class="field"><label for="op-mode">Способ расчёта</label><select id="op-mode" onchange="operationPreview()">${[['tariff','Тариф за единицу обработки'],['machine','Время оборудования'],['manual','Ручная стоимость']].map(([k,v])=>`<option value="${k}" ${o.mode===k?'selected':''}>${v}</option>`).join('')}</select></div><div id="op-panel-tariff"><div class="grid2">${input('measure',t.measure)}<details ${!o.rateProfile?'open':''}><summary>Ставка и условия</summary>${input('rate',t.rate)}</details></div>${['laser','waterjet'].includes(o.type)?`<div class="grid2">${input('pierces','Врезки / проколы на изделие, шт.')}${input('pierceRate','Стоимость врезки / прокола, ₽')}</div>`:''}</div><div id="op-panel-machine"><div class="grid3">${input('minutes','Машинное время на изделие, мин')}${input('hourRate','Ставка оборудования, ₽/ч')}${input('consumables','Дополнительные расходники, ₽/мин')}</div><p class="small">Расходники указывайте только сверх ставки оборудования. Время задаётся вручную по технологической оценке.</p></div><div id="op-panel-manual">${input('manual','Обработка одного изделия, ₽')}</div><details ${!o.rateProfile?'open':''}><summary>Дополнительные условия партии и источник</summary><div class="grid2">${input('setup','Подготовка на всю партию, ₽')}${input('minimum','Минимальная стоимость операции на партию, ₽')}</div><div class="field"><label for="op-source">Основание ставки, дата и условия</label><input id="op-source" value="${esc(o.source||'')}"></div><p class="small">Минимум применяется к обработке вместе с подготовкой. Суммы вводятся в принятой базе затрат: закупочные цены с НДС, без его вычета. НДС продажи добавляется общим калькулятором. Геометрия не определяет время автоматически; раскрой и проверка возможностей станка не выполняются.</p></details><label class="checkrow"><input id="op-confirmed" type="checkbox" ${l?.confirmed?'checked':''}>Параметры и ставки проверены для этого заказа</label><div id="op-preview" class="note info" aria-live="polite"></div><div class="mini-actions"><button class="primary" type="submit">Сохранить операцию</button>${id?`<button type="button" onclick="removeLine('${id}')">Удалить операцию</button>`:''}</div></form>`);if($('op-rate-profile'))$('op-rate-profile').snapshot=o.rateProfile||null;operationPreview();
}
function operationInput(){const o={...operationMetadata,version:1,type:$('op-type').value,mode:$('op-mode').value,material:$('op-material').value,source:$('op-source').value};for(const k of ['setup','minimum','manual','measure','rate','pierces','pierceRate','minutes','hourRate','consumables']){const el=$('op-'+k);o[k]=!el||el.value===''?null:Number(el.value)}if($('op-rate-profile')?.snapshot){o.rateProfile=structuredClone($('op-rate-profile').snapshot);o.rateProfile.modified=Object.entries(o.rateProfile.values).some(([k,v])=>o[k]!==v)}return DomainSchema.operation(o)}
function operationPreview(){const o=operationInput();for(const k of ['tariff','machine','manual'])$('op-panel-'+k).hidden=o.mode!==k;const r=OperationsCore.calculate(o,state.qty);$('op-preview').textContent=r.errors.length?'Заполните параметры выбранного способа расчёта.':`Обработка: ${money(r.unit)} / изделие · подготовка: ${money(r.setup)} / партия · доплата до минимума: ${money(r.minimumExtra)} · итого на ${state.qty} шт.: ${money(r.total)}`}
function saveOperation(e){e.preventDefault();const o=operationInput(),r=OperationsCore.calculate(o,state.qty);if(r.errors.length){$('op-preview').textContent=r.errors.join('; ');return}if(!$('op-name').value.trim()||!$('op-group').value.trim()){toast('Заполните название и группу');return}const id=$('op-id').value,l=state.lines.find(x=>x.id===id)||{...lineFrom(),kind:'work'};Object.assign(l,{name:$('op-name').value.trim(),group:$('op-group').value.trim(),unit:'операция',qty:1,price:r.unit,reserve:0,pack:1,scope:'unit',allocation:'whole',costCategory:'',operation:o,source:OperationsCore.TYPES[o.type].name+' · '+(o.source||'ручные параметры'),confirmed:$('op-confirmed').checked});if(!id)state.lines.push(l);OperationEditorStore.clear(id,o.type);persist();$('modal').close();render()}

function rememberOperationDraft(){if(!$('op-type'))return;try{const draft={id:$('op-id').value,name:$('op-name').value,group:$('op-group').value,confirmed:$('op-confirmed').checked,operation:operationInput()};if(!OperationEditorStore.save(draft))toast('Черновик не сохранён: недостаточно места')}catch{}}
function resumeOperationDraft(){const d=OperationEditorStore.current();if(d)operationDialog(d.id||null,d.operation.type)}
